CREATE OR REPLACE FUNCTION side_lite_private.create_student_profile()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare profile_name text;
begin
  profile_name := btrim(coalesce(new.raw_user_meta_data ->> 'display_name', ''));
  if char_length(profile_name) < 2 or char_length(profile_name) > 80 then
    profile_name := 'Estudiante';
  end if;
  insert into public.lite_profiles (id, display_name) values (new.id, profile_name)
  on conflict (id) do nothing;
  return new;
end $function$

CREATE OR REPLACE FUNCTION side_lite_private.initialize_cycle()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare max_cycles integer;
begin
  select g.cycle_count into max_cycles from public.lite_games g where g.id = new.game_id for update;
  if max_cycles is null or new.number > max_cycles then
    raise exception 'Invalid cycle number' using errcode = '23514';
  end if;
  new.starts_at := clock_timestamp();
  new.ends_at := new.starts_at + interval '120 seconds';
  return new;
end $function$
